export const BODY_REGIONS_BACK = MALE_BODY_REGIONS_BACK;

/**
 * Returns region definitions for the specified gender and view
 * @param {'male'|'female'} gender
 * @param {'front'|'back'} view
 */
export function getBodyRegions(gender = 'male', view = 'front') {
  const isFemale = gender === 'female';
  if (view === 'front') {
    return isFemale ? FEMALE_BODY_REGIONS_FRONT : MALE_BODY_REGIONS_FRONT;
  }
  return isFemale ? FEMALE_BODY_REGIONS_BACK : MALE_BODY_REGIONS_BACK;
}

